void mainImage(out vec4 O, vec2 u) {
    vec2  R = iResolution.xy,  U = u+u - R;
    float a = atan(U.y,U.x)/6.283 ;                               // polar coordinates
    a += ceil( U = 5.*length(U)/R - a ).y;                        // spiral band coordinates
    U.x= 2.6*a*a - iTime;                                         // isometric curvilinear
    a  = dot( U = 2.* fract( U ) - 1. ,                           // cells coordinates
              cos( .4*a*a * max(0.,1.-length(U) ) - vec2(33,0) ));// twist cell space
    O = min(1., a/fwidth(a) +.5)                                  // AA-draw (y>0) in this space
      - pow( U.y*U.y, 5.) + O*0.;                                 // shadow
}
